package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type SessionCache struct {
	mu       sync.Mutex
	sessions map[string]*ClientSession
}

type ClientSession struct {
	Conn        *websocket.Conn
	Credentials *AWSCreds
	LastActive  time.Time
	Buffer      [][]byte
}

type AWSCreds struct {
	AccessKeyID     string `json:"access_key_id"`
	SecretAccessKey string `json:"secret_access_key"`
	SessionToken    string `json:"session_token"`
}

type Message struct {
	Action  string `json:"action"`
	Payload string `json:"payload"`
	Bucket  string `json:"bucket"`
	Key     string `json:"key"`
}

var cache = &SessionCache{sessions: make(map[string]*ClientSession)}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}

	sessionID := r.URL.Query().Get("session_id")
	if sessionID == "" {
		conn.Close()
		return
	}

	// Load credentials from environment for this service account
	creds := &AWSCreds{
		AccessKeyID:     os.Getenv("AWS_ACCESS_KEY_ID"),
		SecretAccessKey: os.Getenv("AWS_SECRET_ACCESS_KEY"),
		SessionToken:    os.Getenv("AWS_SESSION_TOKEN"),
	}

	clientSession := &ClientSession{
		Conn:        conn,
		Credentials: creds,
		LastActive:  time.Now(),
		Buffer:      make([][]byte, 0, 1024),
	}

	cache.mu.Lock()
	// BUG: Never removes old sessions - memory leak with credential retention
	cache.sessions[sessionID] = clientSession
	cache.mu.Unlock()

	for {
		_, msgBytes, err := conn.ReadMessage()
		if err != nil {
			log.Printf("Read error for session %s: %v", sessionID, err)
			// Note: session NOT removed from cache on disconnect
			break
		}

		// Accumulate messages in buffer (never freed)
		clientSession.Buffer = append(clientSession.Buffer, msgBytes)

		var msg Message
		if err := json.Unmarshal(msgBytes, &msg); err != nil {
			continue
		}

		switch msg.Action {
		case "upload":
			go handleS3Upload(clientSession, msg)
		case "debug":
			// Debug endpoint exposes session cache including credentials
			handleDebug(conn)
		}
	}
}

func handleS3Upload(session *ClientSession, msg Message) {
	sess, err := session.Func(session.Credentials, msg.Bucket)
	if err != nil {
		log.Printf("S3 session error: %v", err)
		return
	}

	svc := s3.New(sess)
	_, err = svc.PutObject(&s3.PutObjectInput{
		Bucket: aws.String(msg.Bucket),
		Key:    aws.String(msg.Key),
		Body:   aws.ReadSeekCloser(strings.NewReader(msg.Payload)),
	})
	if err != nil {
		log.Printf("Upload error: %v", err)
	}
}

func (cs *ClientSession) Func(creds *AWSCreds, bucket string) (*session.Session, error) {
	return session.NewSession(&aws.Config{
		Region: aws.String(os.Getenv("AWS_REGION")),
	})
}

func handleDebug(conn *websocket.Conn) {
	cache.mu.Lock()
	defer cache.mu.Unlock()

	// Vulnerability: serializes ALL cached sessions including credentials
	data, _ := json.Marshal(cache.sessions)
	conn.WriteMessage(websocket.TextMessage, data)
}

func dumpSessions(w http.ResponseWriter, r *http.Request) {
	cache.mu.Lock()
	defer cache.mu.Unlock()

	var summary []string
	for id, s := range cache.sessions {
		summary = append(summary, fmt.Sprintf("%s: last_active=%s, buffer_size=%d",
			id, s.LastActive.Format(time.RFC3339), len(s.Buffer)))
	}
	json.NewEncoder(w).Encode(summary)
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
	})
	http.HandleFunc("/sessions", dumpSessions)

	log.Println("WebSocket service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
